---转换活动商店数据
function ActivityOpenLatticeSupplyDialog:ConvertActivityStoreData(requestData)
    local listData = {}
    local products = requestData.products
    for i = 1, #products do
        products[i].nextRefreshLeftSeconds = requestData.nextRefreshLeftSeconds
        local dojo = StoreChestDojo.New()
        dojo:Fill(products[i])
        table.insert(listData, dojo)
        requestData.products = listData
        requestData.activityTimeLeft = checkInt(requestData.remainingTimes)
    end
    return requestData
end

function ActivityOpenLatticeSupplyDialog:GetStoreData()
    local storeData = self.ActivityStoreData
    self:SortStoreData(storeData)
    self.ShownData = storeData
end


function ActivityOpenLatticeSupplyDialog:SortStoreData(storeData)
    table.sort(storeData.products, function(a, b)
        local isSoldOutA = StoreUtils.ProductIsSoldOut(a)
        local isSoldOutB = StoreUtils.ProductIsSoldOut(b)
        if isSoldOutA ~= isSoldOutB then
            return not isSoldOutA
        elseif a.activityUuid ~= b.activityUuid then
            return a.activityUuid > b.activityUuid
        elseif a.pos ~= b.pos then
            return a.pos < b.pos
        else
            return a.productId < b.productId
        end
    end)
end

function ActivityOpenLatticeSupplyDialog:FreshBaseUI()
    local cnt = #self.ShownData.products
    if not self.LoopView.IsListViewInit then
        self.LoopView:InitGridView(cnt, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, cnt)
    end
    self:SetTopGoodsShow()
end

function ActivityOpenLatticeSupplyDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1
    local cell = listView:NewListViewItem("Cell")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.Activity.OpenGrid.ActivityOpenGridSupplyCell")
    if nodeEnv then
        local data = self.ShownData.products[luaIndex]
        local isSoldOut = StoreUtils.ProductIsSoldOut(data)
        nodeEnv:RefreshCell(data)
        nodeEnv:SetBtnCallBack(function()
            if isSoldOut then
                GameUtils.Toast(localize("商品已售罄"))
                return
            end
            if self.activityUuid then
                local currency = next(data.prices) and data.prices[1].currency or 0
                local cost = next(data.prices) and data.prices[1].current or 0
                -- 为0的话是免费商品 不用确认框
                if currency == 0 then
                    self:ActivityStoreBuyHandler(data.productId, currency, 1,cost)
                    return
                end
                local currencyData = GoodsConfMgr:GetGoodsVoById(currency)
                if self:IsCurrencyEnough(currency,cost) then
                    GameUtils.SecondConfirm
                    (
                            localize("确认花费_Num__Name_购买_Name1_？",{_Num_ = cost , _Name_ = currencyData.name , _Name1_ = data.name}),
                            function()
                                self:ActivityStoreBuyHandler(data.productId, currency, 1, cost)
                            end
                    )
                else
                    GameUtils.Toast(localize("_name_不足", {_name_ = currencyData.name}))
                end
            end
        end)
    end
    return cell
end

function ActivityOpenLatticeSupplyDialog:IsCurrencyEnough(currency,cost)
    return (GoodsUtils.GetThingNo(currency) >= cost)
end

function ActivityOpenLatticeSupplyDialog:SetTopGoodsShow()
    local data = self:GetStaticData()
    local goodIds = string.split(data.itemId2,";")
    CfUtils.RefreshTopGoods(goodIds)
end

function ActivityOpenLatticeSupplyDialog:GetStaticData()
    local data = CfUtils.GetCfVo(AutoIds.IdSetting6128, "OpenGridActivityVo", self.activityContentId or 1)
    return data
end

---刷新活动商店数据
function ActivityOpenLatticeSupplyDialog:RefreshActivityStock(productId, buyNum)
    for i, v in ipairs(self.ShownData.products) do
        if checkInt(v.productId) == checkInt(productId) then
            if checkInt(v.stock) == -1 then
                break
            else
                v.currentStock = math.max(0, v.currentStock - buyNum)
            end
        end
    end
    self:FreshBaseUI()
end

function ActivityOpenLatticeSupplyDialog:IsSupplyShopRedDotShow()
    for i, v in ipairs(self.ShownData.products) do
        if  next(checkTable(v.prices)) == nil and v.currentStock > 0 then
            return true
        end
    end
    return false
end


---活动商店购买处理
function ActivityOpenLatticeSupplyDialog:ActivityStoreBuyHandler(productId, price, buyNum, cost)
    local requestData = {
        productId    = productId,
        num          = buyNum,
        currency     = price,
        activityUuid = self.activityUuid,
        activityType = self.activityType
    }
    GameUtils.Request(Interfaces.ActivityOpenGridSupplyProductsBuy, requestData, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then
                if price ~= 0 then
                    local consume = {}
                    table.insert(consume, { ["num"] = - buyNum * cost;
                                            ["goodsId"] = price; })
                    GoodsUtils.DrawRewards(consume)
                end
                GoodsUtils.DrawRewards(responseData.rewards)
                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                self:RefreshActivityStock(productId, buyNum)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
        end
    end)
end

return ActivityOpenLatticeSupplyDialog